#!/bin/sh
# nep_stubs.c (generated by the lifter's genrt.py) defines an abort stub for every .nep CLR unit.  The native shell (runtime/shell.c)
# provides four of them, so drop those definitions: usage gen_nep.sh in.c out.c
sed -e '/^void f_579bf0(/d' -e '/^void f_579bc0(/d' -e '/^void f_579a50(/d' -e '/^void f_579ad0(/d' "$1" > "$2"
